/**
 * @name Regular Expression Denial of Service (ReDoS)
 * @description User-controlled input flowing into complex regular expressions can cause denial of service
 * @kind path-problem
 * @problem.severity error
 * @id py/redos
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for re.compile, re.match, re.search, re.fullmatch, re.findall, re.finditer
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("re").getMember(["compile", "match", "search", "fullmatch", "findall", "finditer"]).getACall() and
      sink = call.getArg(0)  // Pattern argument
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "ReDoS vulnerability: user input flows into regular expression at $@.", source.getNode(), "user input"

/**
 * @name Integer overflow or arithmetic vulnerabilities
 * @description Untrusted numeric input flowing into arithmetic operations could lead to integer overflow or DoS
 * @kind path-problem
 * @problem.severity error
 * @id py/integer-overflow
 * @tags security
 *        external/cwe/cwe-190
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module IntegerOverflowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for arithmetic operations with potentially untrusted input
    exists(DataFlow::CallCfgNode call |
      // Check for arithmetic operations in h11 that handle content-length or other numeric HTTP fields
      call = API::moduleImport("h11").getMember("_readers").getMember("readers").getACall() or
      call = API::moduleImport("h11").getMember("_receivebuffer").getMember("ReceiveBuffer").getACall() or
      call = API::moduleImport("h11").getMember("_connection").getMember("Connection").getACall()
    |
      sink = call.getArg(0)  // First argument often contains numeric values
    )
  }
}

module IntegerOverflowFlow = TaintTracking::Global<IntegerOverflowConfig>;
import IntegerOverflowFlow::PathGraph

from IntegerOverflowFlow::PathNode source, IntegerOverflowFlow::PathNode sink
where IntegerOverflowFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential integer overflow from $@.", source.getNode(), "user input"
